<?php /** @var \HoloScope\ViewModel\PageViewModel $view */ require_once dirname(__DIR__) . '/helpers.php'; $index=$view->data['index']; $items=$view->data['items']; $collection=$view->data['collection']; ?>
<section class="search-header"><p class="eyebrow"><?= $collection==='slang'?'SLANG DICTIONARY':'PHRASE DICTIONARY' ?></p><h1><?= e($view->heading) ?></h1><p>一般例文ではなく、原文確認と時刻確認を終えた配信内使用例を掲載します。</p></section>
<form class="search-form phrase-search" method="get" action="/holoscope/learning/<?= e($collection) ?>/"><label class="keyword-field"><span>語句・意味</span><input type="search" name="q" value="<?= e($view->data['keyword']) ?>"></label><div class="filter-grid"><?php if($collection==='phrases'): ?><label><span>分類</span><select name="category"><option value="">すべて</option><?php foreach($index['categories']??[] as $value=>$label): ?><option value="<?= e($value) ?>"<?= $view->data['category']===$value?' selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><?php endif; ?><label><span>使用域</span><select name="register"><option value="">すべて</option><?php foreach($index['registers']??[] as $value=>$label): ?><option value="<?= e($value) ?>"<?= $view->data['register']===$value?' selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label></div><div class="form-actions"><button class="button">絞り込む</button><a href="/holoscope/learning/<?= e($collection) ?>/">条件をクリア</a></div></form>
